def flow(*items, note=''): return dict(kind='flow', items=items, note=note)
def compare(*items, note=''): return dict(kind='compare', items=items, note=note)
def rows(headers, data, note=''): return dict(kind='table', headers=headers, data=data, note=note)
def code(cell, keys, *items, note=''): return dict(kind='code', cell=cell, keys=keys, items=items, note=note)
def special(kind, *items, note=''): return dict(kind=kind, items=items, note=note)

